     1	import { readFileSync } from "node:fs";
     2	import { type Scenario, runScenario } from "./scenario.js";
     3	
     4	const REJECTED_EXIT_CODE = 1;
     5	
     6	// The trust boundary. The scenario schema in the specification is normative, so
     7	// a document that reaches us is taken at its word and asserted to be a
     8	// `Scenario` rather than validated field by field: nothing in the office's rules
     9	// decides what a well-formed document is, and no example asks this adapter to
    10	// answer a malformed one. A document that breaks the schema therefore fails as a
    11	// parse error or as a shape mismatch inside the rules, and is reported by the
    12	// same refusal path as a domain rejection below -- deliberately, not by
    13	// oversight. Validating here would invent a contract the specification does not
    14	// state and would move the decision out of the office and into the transport.
    15	function readScenarioFromStdin(): Scenario {
    16	  return JSON.parse(readFileSync(0, "utf8")) as Scenario;
    17	}
    18	
    19	// The office either answers every step or refuses the whole document: a refusal
    20	// writes its description to stderr and leaves stdout empty. A refusal always
    21	// arrives as a thrown `Error` carrying a description and nothing else, which is
    22	// the only outbound contract the rules offer, so translating it needs no domain
    23	// knowledge -- just its message, an empty stdout, and a non-zero exit.
    24	function main(): void {
    25	  try {
    26	    const results = runScenario(readScenarioFromStdin());
    27	    process.stdout.write(`${JSON.stringify({ results })}\n`);
    28	  } catch (rejection) {
    29	    process.stderr.write(`${(rejection as Error).message}\n`);
    30	    process.exitCode = REJECTED_EXIT_CODE;
    31	  }
